sections.content:
/* Element selector */
h1 { color: navy; }

/* Class selector */
.btn { padding: 8px 16px; }

/* ID selector (highest specificity — use sparingly) */
#hero { min-height: 100vh; }

/* Attribute selector */
input[type="email"] { border-color: blue; }

/* Descendant combinator */
.card p { font-size: 14px; }

/* Direct child combinator */
.nav > li { display: inline-block; }

/* Adjacent sibling */
h2 + p { margin-top: 0; }

/* Pseudo-class */
a:hover { text-decoration: underline; }
input:focus { outline: 2px solid blue; }
li:nth-child(odd) { background: #f5f5f5; }

/* Pseudo-element */
p::first-line { font-weight: bold; }
.quote::before { content: '\"'; }

/* Specificity: 0,0,1 — element */
p { color: black; }

/* Specificity: 0,1,0 — class */
.text { color: gray; }

/* Specificity: 0,1,1 — class + element */
p.text { color: blue; }

/* Specificity: 1,0,0 — id */
#intro { color: red; }

/* Last resort: !important (avoid in production) */
p { color: purple !important; }

.card {
  width: 300px;       /* content width */
  padding: 24px;      /* space inside border */
  border: 2px solid #ccc; /* visible boundary */
  margin: 16px;       /* space outside border */
}

/* Default box-sizing: content-box
   Total width = 300 + 24*2 + 2*2 = 352px — SURPRISE!

   Fix: border-box makes width include padding and border */
*, *::before, *::after {
  box-sizing: border-box;
}
/* Now: width: 300px IS the total — padding and border are inside */

/* block: full width, starts on new line */
div { display: block; }

/* inline: flows with text, no width/height */
span { display: inline; }

/* inline-block: flows with text, accepts width/height */
.badge { display: inline-block; }

/* none: removes from layout completely */
.hidden { display: none; }

/* flex and grid: covered in Module 3 */
.container { display: flex; }

/* static: default — in normal document flow */
.normal { position: static; }

/* relative: offset from its own position (leaves space) */
.nudged { position: relative; top: 10px; left: 5px; }

/* absolute: removed from flow, positioned to nearest
   positioned ancestor */
.tooltip {
  position: absolute;
  top: 100%;
  left: 0;
}

/* fixed: relative to viewport — stays during scroll */
.sticky-nav {
  position: fixed;
  top: 0;
  width: 100%;
}

/* sticky: hybrid — relative until threshold, then fixed */
th { position: sticky; top: 0; }

:root {
  --color-primary: #6366f1;
  --color-text: #1a1a2e;
  --spacing-md: 16px;
  --radius-lg: 12px;
  --font-body: 'Inter', sans-serif;
}

.btn {
  background: var(--color-primary);
  padding: var(--spacing-md);
  border-radius: var(--radius-lg);
  font-family: var(--font-body);
}

/* Dark mode: just override variables */
@media (prefers-color-scheme: dark) {
  :root {
    --color-text: #e2e8f0;
    --color-primary: #818cf8;
  }
}

/* Minimal modern reset */
*, *::before, *::after { box-sizing: border-box; }
* { margin: 0; padding: 0; }
body { font-family: var(--font-body); line-height: 1.5; }
img, video { max-width: 100%; display: block; }
button { cursor: pointer; border: none; background: none; }
